/* Learning content. Everything refers to the real repository snapshot.
   Items marked unverified:true are about the assignment brief / marking, which is
   NOT inside the repository, so the app flags them. */
window.C = {};

C.topics = {
  overview: "Big picture", arch: "Architecture & design", main: "main.py & menus", db: "Database & files",
  models: "Student & Subject models", valid: "Validation (regex)", student: "Login & register", enrol: "Enrolment",
  admin: "Admin system", gui: "GUI (Tkinter)", exc: "Exceptions", test: "Testing", contrib: "Your contribution",
};

/* ============================================================ LESSONS */
C.lessons = [
{ id: "L1", topic: "overview", title: "What does this project do?", mins: 4, cards: [
  { h: "In one sentence", b: `It is a university enrolment system. <b>Students</b> can register, log in and enrol in up to <b>4 subjects</b>. <b>Admins</b> can see, group, partition and remove students. All data is saved in a file called <code>students.data</code>.` },
  { h: "Two apps, one data file", b: `<b>CLIUniApp</b> runs in the terminal: <code>python3 main.py</code>.<br><b>GUIUniApp</b> opens windows: <code>python3 gui_main.py</code>.<br>Both use the <b>same</b> <code>students.data</code> file and the <b>same</b> controller classes. So a student registered in the CLI can log in to the GUI.` },
  { h: "Three menus in the CLI", b: `1. <b>University System</b>: A / S / X<br>2. <b>Admin System</b>: c g p r s x<br>3. <b>Student System</b>: l r x → after login → <b>Student Course Menu</b>: c e r s x` },
  { h: "Four windows in the GUI", b: `Login window → Enrolment window → Subjects window. Plus an Exception window (error pop-up). No register and no admin in the GUI.` },
  { h: "Say it like this", say: true, b: `"Our system has a command-line app and a GUI app. They share one data file and the same controllers. Students register, log in and enrol in up to four subjects with random marks. Admins can view, group by grade, split into pass and fail, and remove students."` },
]},
{ id: "L2", topic: "arch", title: "The layers (who does what)", mins: 5, cards: [
  { h: "Think of a restaurant", b: `<b>Menu / window</b> = the waiter (talks to you).<br><b>Controller</b> = the chef (does the work, follows the rules).<br><b>Model</b> = the dish (Student, Subject).<br><b>Database</b> = the fridge (stores everything in <code>students.data</code>).` },
  { h: "The real folders", b: `<code>main.py</code>, <code>gui_main.py</code> → start the apps<br><code>admin_system/</code>, <code>student_system/</code> → menus + controllers<br><code>gui_system/</code> → Tkinter windows<br><code>models/</code> → Student and Subject classes<br><code>database/</code> → file reading and writing<br><code>utils/</code> → constants and custom exceptions<br><code>tests/</code> → unittest tests` },
  { h: "Why separate them?", b: `Because the <b>same</b> EnrolmentController is used by the CLI menu AND the GUI window. The rules (max 4 subjects, saving) are written once. If we put the rules inside the menu, the GUI would need a copy.` },
  { h: "Dependency injection (simple)", b: `<code>main.py</code> creates ONE Database and <b>passes it in</b>: <code>StudentController(database)</code>. The controller does not create its own. Benefit: everyone shares the same data, and tests can pass in a fake database.` , code: { file: "main.py", from: 13, to: 22 } },
  { h: "Say it like this", say: true, b: `"We split the code into layers. Menus and windows only handle input and output. Controllers hold the rules. Models describe a student and a subject. The Database class is the only code that touches the file. That is why the CLI and GUI can share the same controllers."` },
]},
{ id: "L3", topic: "main", title: "main.py step by step", mins: 4, cards: [
  { h: "Start-up", b: `Line 14 opens <code>students.data</code>. Lines 17-22 build controllers and menus.`, code: { file: "main.py", from: 12, to: 22 } },
  { h: "The loop", b: `<code>while True</code> repeats forever. Each time it asks for A, S or X. <code>.strip().upper()</code> means <code>" s "</code> works like <code>S</code>.`, code: { file: "main.py", from: 25, to: 39 } },
  { h: "Only main is forgiving", b: `The admin and student menus do <b>not</b> strip or change case. Typing <code>L</code> at "Student system (l/r/x)" gives "Invalid input". Know this before the demo!` },
  { h: "The __name__ guard", b: `<code>if __name__ == "__main__": main()</code> means: only start when this file is run directly. Tests import <code>main</code> without starting the loop.`, code: { file: "main.py", from: 42, to: 43 } },
]},
{ id: "L4", topic: "db", title: "students.data and the Database class", mins: 6, cards: [
  { h: "What is in the file?", b: `A <b>JSON list</b>. Each item is one student:<pre>{ "id": "673358", "name": "John Smith",
  "email": "john.smith@university.com",
  "password": "Password123",
  "subjects": [ {"id": "541", "mark": 72, "grade": "C"} ] }</pre>` },
  { h: "Loading", b: `If the file is missing, it is created with <code>[]</code>. Then <code>json.load</code> reads it into <code>self.students</code> (a list of dictionaries).`, code: { file: "database/database.py", from: 19, to: 40 } },
  { h: "Saving", b: `<code>save_students()</code> rewrites the WHOLE file with <code>json.dumps(..., indent=2)</code>. Every change calls it, so the file is always up to date.`, code: { file: "database/database.py", from: 42, to: 50 } },
  { h: "CRUD", b: `<b>C</b>reate → <code>create_student</code> (register)<br><b>R</b>ead → <code>get_all_students</code>, <code>get_student_by_id</code>, <code>get_student_by_email</code><br><b>U</b>pdate → <code>update_student</code> (enrol, remove subject, change password)<br><b>D</b>elete → <code>delete_student</code> (admin r), <code>delete_all_students</code> (admin c)` },
  { h: "A bug story you can tell", b: `Minh's old <code>update_student</code> used the loop variable name <code>student</code> — the same as the parameter. The loop overwrote the new data, so the OLD record was saved. Rafeed renamed them <code>updated_student</code> and <code>existing_student</code>.`, code: { file: "database/database.py", from: 84, to: 108 } },
  { h: "Say it like this", say: true, b: `"The Database class is the only part that reads or writes students.data. It loads the JSON list once at start-up, and after every create, update or delete it rewrites the whole file. Every method catches errors and raises our own named exception."` },
]},
{ id: "L5", topic: "models", title: "Student and Subject classes", mins: 6, cards: [
  { h: "Subject", b: `A Subject has <code>id</code> (3-digit text like "097"), <code>mark</code> (25-100) and <code>grade</code>. The grade is calculated from the mark when the subject is created.`, code: { file: "models/subject.py", from: 85, to: 93 } },
  { h: "Grades", b: `below 50 → <b>Z</b>, below 65 → <b>P</b>, below 75 → <b>C</b>, below 85 → <b>D</b>, otherwise <b>HD</b>. Each constant is the TOP of its band, so 65 is C (not P).`, code: { file: "models/subject.py", from: 39, to: 48 } },
  { h: "Random but unique ID", b: `<code>generate_subject_id</code> lists every free ID from 001 to 999, then picks one with <code>random.choice</code>. It can never pick a duplicate and never loops forever.`, code: { file: "models/subject.py", from: 57, to: 72 } },
  { h: "Objects ↔ dictionaries", b: `JSON cannot store objects. <code>Student.convert_to_file_data()</code> turns a Student (and its Subjects via <code>to_dict()</code>) into dictionaries. <code>Student.create_from_file_data()</code> (a <b>class method</b>) rebuilds the objects.`, code: { file: "models/student.py", from: 10, to: 39 } },
  { h: "__str__", b: `When the CLI prints a subject, Python calls <code>__str__</code>, giving <code>[ Subject::541 -- mark = 72 -- grade =   C ]</code>.`, code: { file: "models/subject.py", from: 105, to: 110 } },
  { h: "Say it like this", say: true, b: `"A Subject gets a unique random three-digit ID and a random mark from 25 to 100. The grade comes from calculate_grade. A Student holds Subject objects in memory; to save, we convert them to dictionaries, and to load we rebuild them with a class method."` },
]},
{ id: "L6", topic: "valid", title: "Email and password rules (regex)", mins: 5, cards: [
  { h: "Email", b: `<code>^[a-zA-Z]+\\.[a-zA-Z]+@university\\.com$</code><br>letters . letters @university.com — nothing else.<br>✅ john.smith@university.com<br>❌ john@university.com (no dot)<br>❌ john.smith2@university.com (digit)<br>❌ john.smith@uni.com` },
  { h: "Password", b: `<code>^[A-Z][a-zA-Z]{4,}[0-9]{3,}$</code><br>Capital first, then 4+ letters (5+ letters total), then 3+ digits, then nothing.<br>✅ Helloworld123, Password123<br>❌ password123 (no capital)<br>❌ Pass123 (only 4 letters)<br>❌ Hello12 (only 2 digits)<br>❌ Hello123a (letter after digits)` },
  { h: "Where it is checked", b: `<code>is_valid_credentials()</code> for CLI login and register. <code>login_gui()</code> checks only the email format. <code>EnrolmentMenu.change_password()</code> checks the new password.`, code: { file: "student_system/student_controller.py", from: 24, to: 38 } },
  { h: "re.match", b: `<code>re.match(pattern, text)</code> returns a match object if the text fits from the start, or <code>None</code>. The <code>$</code> at the end makes sure nothing extra follows.` },
]},
{ id: "L7", topic: "student", title: "Register and login (CLI)", mins: 5, cards: [
  { h: "Register flow", b: `Student Sign Up → ask Email + Password until both formats are OK → if the email exists: "Student X already exists" → ask Name (not empty) → new unique 6-digit ID → save → "Enrolling Student Name".`, code: { file: "student_system/student_controller.py", from: 46, to: 64 } },
  { h: "Unique 6-digit ID", b: `<code>f"{random.randint(1, 999999):06d}"</code> pads to 6 digits (42 → "000042"). The loop repeats if the ID is taken.`, code: { file: "student_system/student_controller.py", from: 40, to: 44 } },
  { h: "Login flow", b: `Student Sign In → ask Email + Password until formats are OK → find by email → wrong email or wrong password: "Student does not exist" → otherwise return a Student → StudentMenu opens the Course Menu.`, code: { file: "student_system/student_controller.py", from: 66, to: 75 } },
  { h: "Tricky detail", b: `The credential loop has no exit. If you type a bad format you MUST type a valid format to escape. Plan your demo inputs!` },
]},
{ id: "L8", topic: "enrol", title: "Enrolment (Course Menu)", mins: 6, cards: [
  { h: "The menu", b: `c = change password, e = enrol, r = remove, s = show, x = exit. Input is stripped and lower-cased.`, code: { file: "student_system/enrolment_menu.py", from: 27, to: 46 } },
  { h: "Enrol", b: `Limit check FIRST: 4 subjects → <code>EnrolmentLimitError</code> → red "Students are allowed to enrol in 4 subjects only." Otherwise new random subject → save → "Enrolling in Subject-XXX" → "You are now enrolled in N out of 4 subjects".`, code: { file: "student_system/enrolment_controller.py", from: 31, to: 49 } },
  { h: "Remove", b: `Pads the ID (97 → 097), finds it, removes it and saves. Not found → <code>SubjectNotFoundError</code> → "Subject 5 does not exist".`, code: { file: "student_system/enrolment_controller.py", from: 51, to: 70 } },
  { h: "Change password", b: `Ask until the format is valid, then ask Confirm until it matches, then save.`, code: { file: "student_system/enrolment_menu.py", from: 88, to: 108 } },
  { h: "Saving", b: `Every change calls <code>save_student()</code> → <code>convert_to_file_data()</code> → <code>database.update_student()</code> → file rewritten.`, code: { file: "student_system/enrolment_controller.py", from: 76, to: 82 } },
]},
{ id: "L9", topic: "admin", title: "Admin features", mins: 6, cards: [
  { h: "Average mark", b: `Sum of subject marks ÷ number of subjects. No subjects → 0.0 (avoids dividing by zero). Returns <code>(average, grade)</code>.`, code: { file: "admin_system/admin_controller.py", from: 28, to: 42 } },
  { h: "s = show", b: `Prints all students in one list: <code>[John Smith :: 673358 --> GRADE: C - MARK: 68.25, ...]</code> or <code>&lt;Nothing to display&gt;</code>.` },
  { h: "g = group", b: `"GRADE GROUPING" then one line per grade that has students, e.g. <code>HD --> [Chris Taylor :: 557301 --> GRADE: HD - MARK: 89.0]</code>.` },
  { h: "p = partition", b: `"PASS/FAIL PARTITIONING" then <code>FAIL --> [...]</code> and <code>PASS --> [...]</code>. Pass means average ≥ 50.` },
  { h: "r and c", b: `r asks "REMOVE BY ID: " (type all 6 digits). Unknown → "Student does not exist". c deletes EVERYONE with no question — back up the file first!` },
]},
{ id: "L10", topic: "gui", title: "The GUI with Tkinter", mins: 7, cards: [
  { h: "Windows", b: `<b>LoginWindow</b> is the root (<code>tk.Tk</code>). <b>EnrolmentWindow</b>, <b>SubjectWindow</b>, <b>ExceptionWindow</b> are <code>tk.Toplevel</code> windows on top of it.` },
  { h: "Widgets", b: `<code>Label</code> (text), <code>Entry</code> (typing box), <code>Button</code> (with <code>command=</code> function), <code>LabelFrame</code> (box with a title), <code>StringVar</code> (holds the typed text).`, code: { file: "gui_system/login_window.py", from: 44, to: 75 } },
  { h: "Layout", b: `<code>pack()</code> stacks widgets top to bottom. <code>grid(row, column)</code> places them in a table. Inside the LabelFrame they use grid; the main window uses pack. Never mix both in the SAME container.` },
  { h: "Event loop", b: `<code>mainloop()</code> waits for clicks and calls the button functions. The program does not move "line by line" any more; it reacts to events.` },
  { h: "Modal error window", b: `<code>transient</code> keeps it on top, <code>grab_set</code> blocks other windows, <code>wait_window</code> pauses until OK is pressed.`, code: { file: "gui_system/exception_window.py", from: 15, to: 42 } },
  { h: "Shared logic", b: `EnrolmentWindow uses the SAME EnrolmentController as the CLI. The 4-subject limit raises the same <code>EnrolmentLimitError</code>, shown here in an ExceptionWindow.`, code: { file: "gui_system/enrolment_window.py", from: 84, to: 100 } },
]},
{ id: "L11", topic: "gui", title: "⚠️ The GUI login issue (important)", mins: 5, cards: [
  { h: "What the controller returns", b: `<code>login_gui()</code> catches every error itself and RETURNS a pair: <code>(Student, None)</code> or <code>(None, LoginGUIError)</code>.`, code: { file: "student_system/student_controller.py", from: 77, to: 96 } },
  { h: "What the window expects", b: `<code>LoginWindow.login()</code> stores the whole pair in <code>student</code> and expects specific exceptions to be raised.`, code: { file: "gui_system/login_window.py", from: 94, to: 108 } },
  { h: "What really happens", b: `For ANY login (correct or wrong): the login window hides, <code>enrolment_controller.student</code> becomes a tuple, <code>EnrolmentWindow</code> calls <code>get_student_name()</code> → <code>'tuple' object has no attribute 'name'</code> → caught by <code>except Exception</code> → printed in the terminal only.<br><br><span class="tag warn">Verified</span> by running the code with a stand-in Tkinter. <b>Please test <code>python3 gui_main.py</code> on your own computer before the showcase.</b>` },
  { h: "The one-line fix (tell your team)", b: `<pre>student, error = self.student_controller.login_gui(email, password)
if error is not None:
    self.show_message("Login failed", "red")
    ExceptionWindow(self, "Login Failed", "Incorrect email or password.")
    return</pre>The learning coach does NOT change your repository. Your team decides.` },
  { h: "If asked in the showcase", say: true, b: `"We found that login_gui returns a pair, but the window used it as one student. The fix is to unpack the pair and check the error before opening the enrolment window. It shows why the two people writing the caller and the function must agree on the return value."` },
]},
{ id: "L12", topic: "exc", title: "Exceptions (errors) in this project", mins: 5, cards: [
  { h: "Custom exceptions", b: `<code>class EnrolmentLimitError(Exception): pass</code> — a new error type with a clear name. Stored in <code>utils/exception/</code>.` },
  { h: "Rule errors", b: `<code>EnrolmentLimitError</code> (5th subject) and <code>SubjectNotFoundError</code> (remove unknown ID) are <b>raised</b> in the controller and <b>caught</b> in the menu/window, which prints the message.` },
  { h: "Wrapper errors", b: `Database and admin methods use <code>try: ... except Exception as e: print(...); raise SomeError</code>. Low-level problems (bad JSON, file locked) become one clear named error.` },
  { h: "raise vs return", b: `<code>raise</code> stops the function and jumps to the nearest matching <code>except</code>. <code>return</code> gives a value back normally. The GUI login issue is a mix-up between these two!` },
]},
{ id: "L13", topic: "test", title: "Testing", mins: 5, cards: [
  { h: "Run the tests", b: `From the project root: <code>python3 -m unittest discover -s tests</code>. Our run: 9 tests pass; test_gui_main needs Tkinter installed.` },
  { h: "Mocks", b: `<code>patch("main.Database")</code> replaces the real class with a fake (Mock). <code>patch("builtins.input", side_effect=[...])</code> fakes typing. Then <code>assert_called_once_with</code> checks how it was used.`, code: { file: "tests/test_main.py", from: 7, to: 36 } },
  { h: "setUp / tearDown", b: `setUp runs before each test, tearDown after. test_database.py uses a separate file <code>students.data.test</code> and deletes it, so the real data is safe.`, code: { file: "tests/test_database.py", from: 7, to: 12 } },
  { h: "Manual tests", b: `The Requirements & Testing tab has test cases with inputs and expected outputs. Use the simulator to check them.` },
]},
{ id: "L14", topic: "contrib", title: "Explaining your contribution", mins: 4, cards: [
  { h: "Use the facts", b: `The Me tab shows who changed which files (from git history) and comments like "Rafeed's code". Pick your name in Settings.` },
  { h: "A good structure (STAR)", b: `<b>S</b>ituation: what part of the system. <b>T</b>ask: what you had to build. <b>A</b>ction: the classes/functions you wrote and one decision you made. <b>R</b>esult: what works now, and one thing you would improve.` },
  { h: "Example (Rafeed)", say: true, b: `"I built the subject enrolment part: the Subject class, the EnrolmentController and EnrolmentMenu, and all four GUI windows. One decision: the controller raises EnrolmentLimitError, and both the CLI and GUI catch it, so the rule is written once. I also fixed a bug in update_student where a variable name overwrote the new data."` },
  { h: "Example (Willy)", say: true, b: `"I wrote the student login and register logic, the email and password regex in constants.py, and unit tests for main.py and gui_main.py using mocks."` },
  { h: "Example (Minh)", say: true, b: `"I set up the project structure, main.py, the Database class with CRUD methods, the admin system, the custom exceptions, and the database tests."` },
]},
];

/* ======================================================= QUESTION BANK
   level: 1 basic, 2 intermediate, 3 advanced, 4 unexpected
   k: keyword groups used to score a typed answer (any word in a group counts) */
C.questions = [
// overview / arch
{ id: "q1", topic: "overview", level: 1, q: "In simple words, what does your system do?", hints: ["Think about the two kinds of user.", "Students: register, login, enrol. Admins: view and manage."], a: "It is a university enrolment system. Students register, log in and enrol in up to 4 subjects with random marks. Admins can show, group, partition and remove students. Data is saved in students.data.", k: [["student"], ["admin"], ["enrol", "subject"], ["students.data", "file", "save"]] },
{ id: "q2", topic: "overview", level: 1, q: "How do you run the CLI and the GUI?", hints: ["Two different .py files in the root folder."], a: "python3 main.py for the CLI and python3 gui_main.py for the GUI, from the project root.", k: [["main.py"], ["gui_main.py"]] },
{ id: "q3", topic: "arch", level: 2, q: "Why did you separate menus from controllers?", hints: ["Which classes does the GUI reuse?", "Think: input/output vs rules."], a: "Menus only handle input and printing; controllers hold the rules. This lets the GUI reuse the same EnrolmentController and StudentController, so the rules are written once and are easier to test.", k: [["input", "print", "output"], ["rule", "logic"], ["gui", "reuse", "share"]] },
{ id: "q4", topic: "arch", level: 2, q: "How do the CLI and GUI share data?", hints: ["Look at line 15 of gui_main.py."], a: "Both create Database(filename=\"students.data\"), so they read and write the same JSON file. A student registered in the CLI can log in to the GUI.", k: [["students.data", "same file"], ["database"]] , ref: "gui_main.py:15" },
{ id: "q5", topic: "arch", level: 3, q: "What is dependency injection and where do you use it?", hints: ["How does StudentController get its database?"], a: "Passing an object in instead of creating it inside. main.py creates one Database and passes it to StudentController(database) and AdminController(database). Everyone shares the same data, and tests can pass in a mock.", k: [["pass", "inject", "given"], ["database"], ["test", "mock", "share"]], ref: "main.py:17" },
{ id: "q6", topic: "arch", level: 3, q: "Where are the constants stored and why?", hints: ["utils/..."], a: "utils/constants.py, grouped in classes like MarkThresholdConstants. It avoids magic numbers and lets us change a rule in one place.", k: [["constants.py", "constants"], ["one place", "magic", "change"]] },
// main
{ id: "q7", topic: "main", level: 1, q: "What happens if I type a lowercase s at the University System prompt?", hints: ["Look at line 30 of main.py."], a: "It works. strip().upper() turns \" s \" into \"S\", so the student menu opens.", k: [["upper", "capital"], ["student menu", "works", "opens"]], ref: "main.py:30" },
{ id: "q8", topic: "main", level: 2, q: "What happens if I type L (capital) at the Student system menu?", hints: ["Does student_menu.py change the case?"], a: "\"Invalid input\". StudentMenu compares the raw input to \"l\" and does not lower-case it.", k: [["invalid"], ["lower", "case"]], ref: "student_system/student_menu.py:16" },
{ id: "q9", topic: "main", level: 2, q: "Why is there if __name__ == \"__main__\" at the bottom of main.py?", hints: ["What happens when a test imports main?"], a: "So main() only runs when the file is executed directly. When the tests import main, the loop does not start.", k: [["import"], ["test", "directly"]] },
{ id: "q10", topic: "main", level: 1, q: "How does the program end?", hints: ["Which input breaks the loop?"], a: "Typing X at the University System menu prints \"Thank You\" and break exits the while loop.", k: [["x"], ["thank you"], ["break"]] },
// db
{ id: "q11", topic: "db", level: 1, q: "What format is students.data?", hints: ["Which module do you import in database.py?"], a: "JSON: a list of student dictionaries, each with id, name, email, password and subjects.", k: [["json"], ["list", "dictionar"]] },
{ id: "q12", topic: "db", level: 2, q: "What happens if students.data does not exist when the program starts?", hints: ["Lines 23-28 of database.py."], a: "The Database constructor creates it with \"[]\" (an empty list). If that fails it raises CreateDatabaseFileError.", k: [["create"], ["empty", "[]"]], ref: "database/database.py:23" },
{ id: "q13", topic: "db", level: 2, q: "When is the file written?", hints: ["Which method writes? Who calls it?"], a: "After every change: create_student, update_student, delete_student and delete_all_students all call save_students(), which rewrites the whole file.", k: [["save_students", "save"], ["every", "change", "after"]] },
{ id: "q14", topic: "db", level: 2, q: "Name the CRUD operations and the methods for each.", hints: ["Create, Read, Update, Delete."], a: "Create: create_student. Read: get_all_students, get_student_by_id, get_student_by_email. Update: update_student. Delete: delete_student, delete_all_students.", k: [["create_student"], ["get_student"], ["update_student"], ["delete"]] },
{ id: "q15", topic: "db", level: 3, q: "Why does save_students use indent=2?", hints: ["Look at the comment above it."], a: "So the JSON is readable with one field per line. Without it, the whole file is one long line.", k: [["read", "readable"], ["line"]], ref: "database/database.py:47" },
{ id: "q16", topic: "db", level: 3, q: "Explain the bug in Minh's old update_student.", hints: ["Look at the loop variable name and the parameter name."], a: "The loop variable was called student, the same as the parameter. The loop overwrote the parameter, so the old record was written back instead of the new one. It was fixed by renaming to updated_student and existing_student.", k: [["name", "variable"], ["overwr", "same"], ["old"]], ref: "database/database.py:85" },
{ id: "q17", topic: "db", level: 3, q: "Why was students = [] moved from the class body into __init__?", hints: ["Class variable vs instance variable."], a: "In the class body it is a class variable shared by every Database object. In __init__ each object gets its own list, so two databases (e.g. in tests) do not mix data.", k: [["class variable", "shared"], ["own", "each", "instance"]] },
{ id: "q18", topic: "db", level: 4, q: "What happens if someone corrupts students.data (broken JSON)?", hints: ["Look at the second try/except in __init__."], a: "json.load fails; the except prints \"error loading database file: ...\" and raises LoadStudentDataError, so the program stops with a clear error.", k: [["loadstudentdataerror", "error"], ["json"]] },
// models
{ id: "q19", topic: "models", level: 1, q: "What three things does a Subject have?", hints: ["Look at Subject.__init__."], a: "An id (3-digit text like \"097\"), a mark (25 to 100) and a grade.", k: [["id"], ["mark"], ["grade"]] },
{ id: "q20", topic: "models", level: 2, q: "What grade does a mark of 65 get? Why?", hints: ["Each constant is the upper limit of its band."], a: "C. The P band is \"below 65\"; 65 is not below 65, so the next check (below 75) matches: C.", k: [["c"], ["below", "less"]] },
{ id: "q21", topic: "models", level: 2, q: "What does pad_id do and why?", hints: ["zfill"], a: "It turns a number into 3-character text with leading zeros (54 → \"054\"), so \"97\" and \"097\" match when removing.", k: [["zero", "zfill", "3"], ["match", "compare", "same"]], ref: "models/subject.py:16" },
{ id: "q22", topic: "models", level: 3, q: "How do you make sure a new subject ID is unique?", hints: ["free_ids"], a: "generate_subject_id builds a list of every free ID from 001 to 999 that the student does not already have, then random.choice picks one. It can't duplicate and always finishes.", k: [["free", "available"], ["random.choice", "random"]] },
{ id: "q23", topic: "models", level: 3, q: "Why is create_from_file_data a @classmethod?", hints: ["Do you have a Student yet when loading?"], a: "We don't have a Student object yet; we want to build one from a dictionary. A class method is called on the class and returns a new instance (a factory method).", k: [["class"], ["new", "build", "create"], ["dict"]] },
{ id: "q24", topic: "models", level: 3, q: "Why does Student use subjects=None instead of subjects=[]?", hints: ["Mutable default arguments."], a: "A default [] is created once and shared by every Student. Using None and creating a new list inside gives each student their own list.", k: [["shared", "same list"], ["none"], ["own", "new"]] },
{ id: "q25", topic: "models", level: 2, q: "What does __str__ do in Subject?", hints: ["When is it called?"], a: "It returns the text shown when a Subject is printed: [ Subject::541 -- mark = 72 -- grade =   C ].", k: [["print"], ["text", "string"]] },
{ id: "q26", topic: "models", level: 2, q: "Why do we need convert_to_file_data?", hints: ["Can json.dumps save a Student object?"], a: "json can only save dicts, lists, strings and numbers, not our objects. convert_to_file_data turns the Student and its Subjects into dictionaries.", k: [["json"], ["dict"], ["object"]] },
// validation
{ id: "q27", topic: "valid", level: 1, q: "What does a valid email look like?", hints: ["firstname . lastname @ ..."], a: "firstname.lastname@university.com — letters, a dot, letters, then @university.com.", k: [["university.com"], ["dot", "."]] },
{ id: "q28", topic: "valid", level: 1, q: "What are the password rules?", hints: ["Look at PASSWORD_PATTERN."], a: "Starts with a capital letter, at least 5 letters in total, followed by at least 3 digits, nothing else.", k: [["capital", "upper"], ["5", "five", "letters"], ["3", "three", "digit"]] },
{ id: "q29", topic: "valid", level: 2, q: "Is Pass123 a valid password?", hints: ["Count the letters."], a: "No. Only 4 letters (P-a-s-s). It needs a capital + 4 more letters = 5 letters.", k: [["no", "invalid"], ["4", "four", "letters"]] },
{ id: "q30", topic: "valid", level: 2, q: "Is john.smith2@university.com a valid email?", hints: ["Does [a-zA-Z]+ allow digits?"], a: "No. The pattern allows only letters before and after the dot.", k: [["no", "invalid"], ["digit", "number", "letter"]] },
{ id: "q31", topic: "valid", level: 3, q: "What does the $ at the end of the regex do?", hints: ["What if extra text follows?"], a: "It means the end of the text. Without it, Password123abc would match because re.match only checks the start.", k: [["end"], ["extra", "after"]] },
{ id: "q32", topic: "valid", level: 3, q: "Why does change_password check the format?", hints: ["Read the comment on lines 99-101 of enrolment_menu.py."], a: "Login checks the same rules. Without the check, a student could set a password they can never log in with.", k: [["login"], ["never", "same rule"]] },
// student
{ id: "q33", topic: "student", level: 1, q: "What happens when you register with an email that already exists?", hints: ["get_student_by_email"], a: "It prints \"Student <name> already exists\" and returns to the Student system menu without saving.", k: [["already exists"]] },
{ id: "q34", topic: "student", level: 2, q: "How is the student ID generated?", hints: ["random.randint and :06d"], a: "random.randint(1, 999999) formatted with :06d to 6 digits with leading zeros. It repeats until get_student_by_id returns None, so it is unique.", k: [["random"], ["6", "six", "06d"], ["unique", "repeat", "loop"]] },
{ id: "q35", topic: "student", level: 2, q: "What does the CLI print for a correct email format but wrong password?", hints: ["Line 72 of student_controller.py."], a: "\"email and password formats acceptable\" then \"Student does not exist\".", k: [["does not exist"]] },
{ id: "q36", topic: "student", level: 3, q: "Why does a wrong password print \"Student does not exist\" instead of \"Wrong password\"?", hints: ["Security"], a: "The code uses one combined check. It doesn't tell an attacker which part was wrong, but it can confuse a real user. It follows the sample message.", k: [["security", "attacker", "hide"], ["combined", "same", "one"]] },
{ id: "q37", topic: "student", level: 2, q: "Can the user cancel while typing email and password?", hints: ["ask_for_valid_credentials"], a: "No. The while True loop only returns when both formats are valid.", k: [["no"], ["loop", "valid"]] },
// enrol
{ id: "q38", topic: "enrol", level: 1, q: "What is the maximum number of subjects?", hints: ["MAX_SUBJECTS"], a: "4. The 5th enrolment raises EnrolmentLimitError.", k: [["4", "four"]] },
{ id: "q39", topic: "enrol", level: 2, q: "Walk me through what happens when a student presses e.", hints: ["Menu → controller → model → database."], a: "EnrolmentMenu.enrol calls controller.enrol. If there are already 4 subjects it raises EnrolmentLimitError (printed in red). Otherwise create_new_subject makes a unique random ID and random mark, the grade is calculated, it's appended, save_student converts to a dict and update_student rewrites the file. Then it prints \"Enrolling in Subject-XXX\" and the count.", k: [["limit", "4"], ["random"], ["save", "update_student"], ["print", "enrolling"]] },
{ id: "q40", topic: "enrol", level: 2, q: "What happens if I remove subject 97 when I have 097?", hints: ["pad_id"], a: "It works. pad_id turns 97 into \"097\" which matches. It prints \"Dropping Subject-97\".", k: [["pad", "zero"], ["works", "removed", "dropping"]] },
{ id: "q41", topic: "enrol", level: 3, q: "Why is the limit checked before creating the subject?", hints: ["What if it was checked after appending?"], a: "So nothing changes when the limit is reached: no subject is created or saved. The rule is a guard at the start.", k: [["nothing", "before", "guard"]] },
{ id: "q42", topic: "enrol", level: 3, q: "Why does EnrolmentController raise an exception instead of printing the error?", hints: ["Who else uses the controller?"], a: "Because both the CLI menu and the GUI window use it. Each one decides how to show the error (red text vs ExceptionWindow). The controller stays independent of the interface.", k: [["gui", "cli", "both"], ["show", "display", "decide"]] },
{ id: "q43", topic: "enrol", level: 2, q: "When are enrolment changes saved?", hints: ["save_student"], a: "Immediately after every enrol, remove and change password, through save_student → update_student.", k: [["immediately", "every", "after"], ["save_student", "update"]] },
// admin
{ id: "q44", topic: "admin", level: 1, q: "What do g and p do in the admin menu?", hints: ["Grade / Pass"], a: "g groups students by their average grade (Z, P, C, D, HD). p partitions them into PASS (average ≥ 50) and FAIL.", k: [["group", "grade"], ["pass", "fail"]] },
{ id: "q45", topic: "admin", level: 2, q: "How is a student's average calculated? What if they have no subjects?", hints: ["calculate_average_mark_and_grade"], a: "Total of subject marks divided by the number of subjects. With no subjects it is 0.0, to avoid dividing by zero.", k: [["sum", "total", "divide"], ["0", "zero"]] },
{ id: "q46", topic: "admin", level: 3, q: "Why doesn't calculate_average_mark_and_grade store the average in the student dict?", hints: ["Read the comment on lines 25-27."], a: "get_all_students returns the live records. Anything written into them would be saved to students.data next time the file is written, which we don't want.", k: [["live", "same", "real"], ["saved", "file"]] },
{ id: "q47", topic: "admin", level: 2, q: "Why does admin remove need all 6 digits?", hints: ["Is the admin ID padded?"], a: "IDs are stored as 6-character strings and remove_student compares strings without padding, so \"1\" does not match \"000001\".", k: [["string", "text"], ["pad", "zero", "6"]] },
{ id: "q48", topic: "admin", level: 4, q: "What is the risk of pressing c in your demo?", hints: ["Is there a confirmation?"], a: "It deletes every student immediately with no confirmation and saves the empty list. Back up students.data first.", k: [["delete", "clear", "all"], ["confirm", "back"]] },
{ id: "q49", topic: "admin", level: 3, q: "How does the output string remove the last comma?", hints: ["slicing"], a: "output_string[:-2] removes the last two characters, the \", \".", k: [[":-2", "slice", "last two"]] },
// gui
{ id: "q50", topic: "gui", level: 1, q: "Which windows does the GUI have?", hints: ["Four classes in gui_system."], a: "LoginWindow, EnrolmentWindow, SubjectWindow and ExceptionWindow.", k: [["login"], ["enrolment"], ["subject"], ["exception"]] },
{ id: "q51", topic: "gui", level: 2, q: "What is the difference between tk.Tk and tk.Toplevel?", hints: ["How many roots?"], a: "tk.Tk is the main (root) window; there is only one. Toplevel creates extra windows on top of the root. LoginWindow is Tk; the others are Toplevel.", k: [["root", "main"], ["toplevel", "extra"]] },
{ id: "q52", topic: "gui", level: 2, q: "What does mainloop() do?", hints: ["Events"], a: "It starts Tkinter's event loop: it keeps the window open and calls functions when the user clicks or types.", k: [["event", "loop"], ["open", "click", "wait"]] },
{ id: "q53", topic: "gui", level: 2, q: "What is a StringVar?", hints: ["textvariable="], a: "A Tkinter variable holding the text of an Entry. .get() reads it, .set() changes it.", k: [["get"], ["entry", "text"]] },
{ id: "q54", topic: "gui", level: 3, q: "What do transient, grab_set and wait_window do in ExceptionWindow?", hints: ["Modal"], a: "transient keeps it on top of its parent, grab_set sends all input to it (modal), wait_window pauses the code until it is closed.", k: [["top"], ["block", "modal", "input"], ["wait", "pause"]] },
{ id: "q55", topic: "gui", level: 3, q: "Why does EnrolmentWindow use protocol(\"WM_DELETE_WINDOW\", ...)?", hints: ["The login window is hidden."], a: "If the user closes the enrolment window with X, handle_close destroys the root. Otherwise the hidden login window would keep the app running invisibly.", k: [["hidden", "withdraw"], ["close", "destroy"]] },
{ id: "q56", topic: "gui", level: 4, q: "Walk me through logging in on the GUI. Does it work?", hints: ["What does login_gui return?", "What does login_window do with the result?"], a: "As written, no. login_gui returns a tuple (student, error); LoginWindow treats the tuple as the student, hides itself and opens EnrolmentWindow, which fails on get_student_name. The fix is student, error = ...login_gui(...) and checking error before opening the window.", k: [["tuple", "pair"], ["fix", "unpack", "error"]], ref: "gui_system/login_window.py:100" },
{ id: "q57", topic: "gui", level: 3, q: "Why is EnrolmentController created with None in gui_main.py?", hints: ["Who is logged in at start-up?"], a: "Nobody is logged in yet. The login window sets enrolment_controller.student after login.", k: [["no one", "nobody", "not logged", "none"], ["later", "after login"]] },
{ id: "q58", topic: "gui", level: 2, q: "pack vs grid?", hints: ["Look at build_widgets in login_window.py."], a: "pack stacks widgets in order; grid places them by row and column. The login window uses pack for the main window and grid inside the LabelFrame.", k: [["row", "column"], ["stack", "order"]] },
// exceptions
{ id: "q59", topic: "exc", level: 1, q: "What is a custom exception?", hints: ["class X(Exception): pass"], a: "A new error class that inherits from Exception, e.g. EnrolmentLimitError. Its name says exactly what went wrong.", k: [["exception", "inherit"], ["name", "clear"]] },
{ id: "q60", topic: "exc", level: 2, q: "Where is EnrolmentLimitError raised and where is it caught?", hints: ["controller vs menu/window"], a: "Raised in EnrolmentController.enrol; caught in EnrolmentMenu.enrol (red message) and EnrolmentWindow.handle_enrol (ExceptionWindow).", k: [["controller"], ["menu"], ["window"]] },
{ id: "q61", topic: "exc", level: 3, q: "What is the downside of except Exception everywhere?", hints: ["What information gets lost?"], a: "It catches every error, even programming bugs, and replaces them with a general one, which can hide the real cause. The GUI login problem is hidden this way: the AttributeError only appears in the terminal.", k: [["hide", "lost", "everything"], ["bug", "real"]] },
// testing
{ id: "q62", topic: "test", level: 1, q: "How do you run the tests?", hints: ["unittest discover"], a: "python3 -m unittest discover -s tests from the project root.", k: [["unittest"], ["discover", "tests"]] },
{ id: "q63", topic: "test", level: 2, q: "What does patch do in test_main.py?", hints: ["Mock"], a: "It temporarily replaces a real object (like main.Database or builtins.input) with a Mock, so the test can control inputs and check calls without real files or typing.", k: [["replace", "fake", "mock"]] },
{ id: "q64", topic: "test", level: 3, q: "Why does test_database use students.data.test?", hints: ["Real data"], a: "So tests never change the real students.data. tearDown deletes the test file.", k: [["real"], ["delete", "teardown"]] },
{ id: "q65", topic: "test", level: 4, q: "Which important behaviour has no automated test?", hints: ["Look at what tests/ covers."], a: "Enrolment rules (4-subject limit, remove), validation regex, admin grouping/partition, and the GUI login flow have no tests. A test for login_window would have caught the tuple bug.", k: [["enrol", "limit", "regex", "admin", "login"]] },
// design / unexpected
{ id: "q66", topic: "arch", level: 4, q: "If you had one more week, what would you improve?", hints: ["Look at the Findings list."], a: "Fix the GUI login (unpack the tuple), make all menus case-insensitive, use SubjectConstants instead of duplicates, add a confirmation for clear, round averages, and add tests for enrolment and validation.", k: [["login"], ["test"], ["constant", "case", "confirm"]] },
{ id: "q67", topic: "arch", level: 4, q: "Why store passwords in plain text? Is that OK?", hints: ["Real systems hash passwords."], a: "It's fine for this assignment, which uses a simple text file. A real system would store a salted hash (e.g. with hashlib/bcrypt) and never the plain password.", k: [["hash"], ["assignment", "real"]] },
{ id: "q68", topic: "db", level: 4, q: "What happens if two people run the CLI and GUI at the same time?", hints: ["Each loads the file once."], a: "Each program loads the file once and keeps its own copy in memory. The last one to save overwrites the other's changes. There is no locking.", k: [["memory", "copy"], ["overwrite", "last"]] },
{ id: "q69", topic: "models", level: 4, q: "Can two different students have the same subject ID?", hints: ["existing_ids only includes this student's subjects."], a: "Yes. generate_subject_id only avoids IDs the same student already has. Subject IDs are unique per student, not across the system.", k: [["yes"], ["per student", "same student", "only"]] },
{ id: "q70", topic: "enrol", level: 4, q: "What happens to the subject grade if a mark is changed directly in students.data?", hints: ["subject_from_dict and grade"], a: "The old grade is kept because subject_from_dict passes the saved grade. The grade is only recalculated if the \"grade\" key is missing. The admin average is always recalculated from marks.", k: [["kept", "old", "saved"], ["missing", "recalculat"]] },
{ id: "q71", topic: "arch", level: 3, q: "Which OOP ideas do you use?", hints: ["classes, inheritance, encapsulation..."], a: "Classes and objects (Student, Subject, controllers), inheritance (windows inherit tk.Tk/Toplevel, errors inherit Exception), encapsulation (Database hides the file), class methods, special methods (__init__, __str__).", k: [["class", "object"], ["inherit"], ["encapsul", "hide"]] },
{ id: "q72", topic: "main", level: 3, q: "What is printed when the program receives \"foo\" at the main menu?", hints: ["else branch"], a: "\"Invalid input\" and the main menu is shown again.", k: [["invalid input"]] },
// contribution (personalised in app)
{ id: "q73", topic: "contrib", level: 1, q: "What was your individual contribution?", hints: ["Name your files and one function you wrote.", "Use STAR: situation, task, action, result."], a: "Name the files you wrote, explain one function line by line, one design decision, and one improvement.", k: [["file", "class", "function", "wrote", "built"], ["because", "decid", "why"]] },
{ id: "q74", topic: "contrib", level: 2, q: "Show me a line of code you wrote and explain it.", hints: ["Open the Explorer, pick your file, tap a line."], a: "Pick a line, say what it does, why it is there, its inputs and outputs, and what calls it.", k: [["line"], ["does", "because", "why"]] },
{ id: "q75", topic: "contrib", level: 3, q: "What was the hardest problem you solved, and how?", hints: ["Look at your commits in the Me tab."], a: "Describe one real bug or design problem (e.g. update_student overwriting data, objects vs dicts in JSON, sharing the controller with the GUI) and the change you made.", k: [["bug", "problem"], ["fix", "changed", "solved"]] },
{ id: "q76", topic: "contrib", level: 2, q: "How did your team use Git?", hints: ["Branches and pull requests."], a: "We used feature branches (e.g. feat/main-entry-tests, subject-class-rafeed, task/refactor-gui) and merged them into main with pull requests on GitHub.", k: [["branch"], ["pull request", "merge", "pr"]] },
];

